                return

        # An optimistic lexicographic bound permits pruning without changing
        # the selected maximum version vector.
        upper = []
        for name in names:
            if name in installed:
                upper.append(installed[name]['version'])
            elif name in needed:
                options = candidates(name, limits.get(name, []))
                upper.append(max(row['version'] for row in options))
            else:
